async function verify(raw,sig,secret){if(!secret||!sig)return false;const parts=Object.fromEntries(sig.split(",").map(x=>x.split("=",2)));if(!parts.t||Math.abs(Date.now()/1000-Number(parts.t))>300)return false;const k=await crypto.subtle.importKey("raw",new TextEncoder().encode(secret),{name:"HMAC",hash:"SHA-256"},false,["sign"]);const v=await crypto.subtle.sign("HMAC",k,new TextEncoder().encode(parts.t+"."+raw));const hex=[...new Uint8Array(v)].map(x=>x.toString(16).padStart(2,"0")).join("");return (parts.v1||"").split(",").includes(hex);}
function splitReceiptOptions(value){const chunks=[];let current="";const encoder=new TextEncoder();for(const char of String(value||"")){if(encoder.encode(current+char).length>450){chunks.push(current);current=char;}else current+=char;if(chunks.length>=40)throw new Error("Too many item customisations");}if(current)chunks.push(current);return chunks;}
function readReceiptOptions(product){if(!product)return "";const meta=product.metadata||{};if(meta.receipt_option_count!==undefined){const count=Number(meta.receipt_option_count);if(!Number.isInteger(count)||count<1||count>40)throw new Error("Invalid receipt option count");let result="";for(let j=0;j<count;j++){const key="receipt_option_"+String(j).padStart(2,"0");if(typeof meta[key]!=="string")throw new Error("Missing receipt options: "+key);result+=meta[key];}return result;}return String(product.description||"");}
async function savePaidKitchenOrder(session,env){
 if(!env.DB)throw new Error("Orders database is not bound");
 const m=session.metadata||{};
 if(m.order_source!=="website")return;
 const existing=await env.DB.prepare("SELECT id FROM orders WHERE stripe_session_id=?").bind(session.id).first();
 if(existing)return; // Webhook retries must not create duplicate orders or items.
 const response=await fetch("https://api.stripe.com/v1/checkout/sessions/"+encodeURIComponent(session.id)+"/line_items?limit=100&expand%5B%5D=data.price.product",{headers:{Authorization:"Bearer "+env.STRIPE_SECRET_KEY}});
 if(!response.ok)throw new Error("Could not retrieve paid order items from Stripe");
 const payload=await response.json();
 if(payload.has_more)throw new Error("Order exceeds first Stripe line-item page");
 const lines=payload.data||[];
 const orderId=crypto.randomUUID();
 const total=Number(session.amount_total||0);
 const lineProductName=x=>String(x.price&&x.price.product&&typeof x.price.product==="object"&&x.price.product.name||x.description||"Hungry Fox item");
 const adjustment=lines.filter(x=>lineProductName(x)==="Delivery and minimum-order adjustment").reduce((sum,x)=>sum+Number(x.amount_total||0),0);
 const insert=env.DB.prepare("INSERT OR IGNORE INTO orders (id,stripe_session_id,order_reference,customer_name,customer_phone,customer_email,delivery_address,postcode,delivery_zone,notes,subtotal_pence,delivery_pence,total_pence,payment_status,kitchen_status) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,'paid','NEW')").bind(orderId,session.id,session.id.slice(-8).toUpperCase(),String(m.customer_name||"Customer"),String(m.customer_phone||""),String(session.customer_details?.email||session.customer_email||m.customer_email||""),String(m.delivery_address||""),String(m.postcode||""),String(m.delivery_zone||""),String(m.notes||""),total-adjustment,adjustment,total);
 const itemStatements=lines.filter(x=>lineProductName(x)!=="Delivery and minimum-order adjustment").map(x=>{
  const label=lineProductName(x);
  return env.DB.prepare("INSERT INTO order_items(order_id,product_name,quantity,unit_price_pence,options) SELECT ?,?,?,?,? WHERE EXISTS (SELECT 1 FROM orders WHERE id=?)").bind(orderId,label,Number(x.quantity||1),Math.round(Number(x.amount_subtotal||0)/Math.max(1,Number(x.quantity||1))),readReceiptOptions(x.price&&x.price.product&&typeof x.price.product==="object"?x.price.product:null),orderId);
 });
 await env.DB.batch([insert,...itemStatements]);
}

