 for(const refund of refunds){
  if(!refund.id||!refund.id.startsWith("re_"))continue;
  const key=refund.metadata?.hungryfox_refund_key;
  const status=refund.status==="succeeded"?"succeeded":refund.status==="failed"?"failed":refund.status==="canceled"?"canceled":"pending";
  if(env.DB){
   if(key)await env.DB.prepare("UPDATE order_refunds SET stripe_refund_id=?,status=?,updated_at=CURRENT_TIMESTAMP WHERE idempotency_key=?").bind(refund.id,status,key).run();
   else await env.DB.prepare("UPDATE order_refunds SET status=?,updated_at=CURRENT_TIMESTAMP WHERE stripe_refund_id=?").bind(status,refund.id).run();
  }
 }
 return new Response("ok");
